require_once('dbstring.php');
require_once('alumni-utils.php');
alumni_ensure_tables($con);
$events=mysqli_query($con,"SELECT title,eventdate,venue,description FROM tblalumnievent WHERE status='planned' AND eventdate>=NOW() ORDER BY eventdate ASC LIMIT 12");
